#!/bin/sh
for c in tesseract file;do command -v $c>/dev/null||exit 2;done;d=$(mktemp -d)||exit 3;d=$(realpath "$d")||exit 3;trap 'rm -rf "$d"' 0;for x in ./*;do [ -f "$x" ]||continue;m=$(file -Lb --mime-type "$x");case $m in application/pdf|image/*)echo "$x";;esac;done>"$d/F";[ -s "$d/F" ]||exit 4;echo Files:;nl -ba "$d/F";printf 'File# ';read n;f=$(sed -n "$n p" "$d/F");[ -n "$f" ]||exit 5;tesseract --list-langs 2>/dev/null|sed '1d;/^osd$/d'>"$d/L";echo OCR-languages:;nl -ba "$d/L";printf 'OCR# ';read n;L=$(sed -n "$n p" "$d/L");b=${f#./};b=${b%.*};o=./$b.ocr.txt;m=$(file -Lb --mime-type "$f");:>"$o";if [ "$m" = application/pdf ];then if command -v mutool>/dev/null;then mutool draw -q -F png -r ${DPI:-250} -o "$d/p-%04d.png" "$f"||exit 8;set -- "$d"/p-*.png;else command -v pdftoppm>/dev/null||exit 8;pdftoppm -r ${DPI:-250} -png "$f" "$d/p" 2>"$d/e"||exit 8;set -- "$d"/p-*.png;fi;else set -- "$f";fi;P=0;Z=1;Q=1;A=0;for x;do P=$((P+1));echo OCR:$P;for s in 3 6 11;do tesseract "$x" "$d/$P.$s" -l "$L" --psm $s 2>/dev/null||exit 9;tr -s '[:space:]' ' '<"$d/$P.$s.txt">"$d/$P.$s.n";done;cmp -s "$d/$P.3.n" "$d/$P.6.n"&&cmp -s "$d/$P.3.n" "$d/$P.11.n"||Z=0;if cmp -s "$d/$P.3.n" "$d/$P.6.n"||cmp -s "$d/$P.3.n" "$d/$P.11.n";then q=3;elif cmp -s "$d/$P.6.n" "$d/$P.11.n";then q=6;else q=3;Q=0;A=$((A+1));fi;cat "$d/$P.$q.txt">>"$o";done;h(){ [ "$1" = 1 ]&&echo 0||echo '>0';};echo "TXT=$o OCR=$L pages=$P ambiguous=$A H_strict=$(h $Z) H_task=$(h $Q) zero_strict=$([ $Z = 1 ]&&echo true||echo false) zero_task=$([ $Q = 1 ]&&echo true||echo false)"
